INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1773605, 242148, 8860, '<td valign="top">One of the best ballon shots I''ve seen = great light and choice of moment. Will undoubtedly score high if not ribbon the blue. Very serene with a tangible silence.</td>', 'One of the best ballon shots I''ve seen = great light and choice of moment. Will undoubtedly score high if not ribbon the blue. Very serene with a tangible silence.', '2005-10-10 06:36:29.000000', NULL, 1),
(1773609, 242137, 29474, '<td valign="top">While not a technically perfect picture, it is one of the VERY few in this challenge that are actually on topic. Well done.</td>', 'While not a technically perfect picture, it is one of the VERY few in this challenge that are actually on topic. Well done.', '2005-10-10 06:49:16.000000', NULL, 1),
(1773614, 240323, 29474, '<td valign="top">Cute child. But I don''t see any celebration. Is this the same photo-shoot as the complementary colours picture?</td>', 'Cute child. But I don''t see any celebration. Is this the same photo-shoot as the complementary colours picture?', '2005-10-10 07:00:02.000000', NULL, 1),
(1773615, 241920, 29474, '<td valign="top">Very cute photograph. But I don''t see any sign of celebration!</td>', 'Very cute photograph. But I don''t see any sign of celebration!', '2005-10-10 07:04:08.000000', NULL, 1),
(1773619, 241984, 29474, '<td valign="top">At last. A real celebratory photgraph. Technically not the strongest, but man is it good to see something that is not contrived for the challenge. I would have preferred to have seen more of the runners and less of the sponsors logos at the top of the picture.</td>', 'At last. A real celebratory photgraph. Technically not the strongest, but man is it good to see something that is not contrived for the challenge. I would have preferred to have seen more of the runners and less of the sponsors logos at the top of the picture.', '2005-10-10 07:06:31.000000', NULL, 1),
(1773626, 241731, 28299, '<td valign="top">Nice capture and use of negative space.</td>', 'Nice capture and use of negative space.', '2005-10-10 07:27:04.000000', NULL, 1),
(1773647, 241931, 29474, '<td valign="top">Wonderful. At last a picture that can be considered celebratory. And one of the better ones. Not sure about the smoke and flames at the bottom of the picture. Did you try alternatives with it cropped out?</td>', 'Wonderful. At last a picture that can be considered celebratory. And one of the better ones. Not sure about the smoke and flames at the bottom of the picture. Did you try alternatives with it cropped out?', '2005-10-10 08:08:59.000000', NULL, 1),
(1773651, 241701, 29474, '<td valign="top">Anti-celebration? This is a odd picture. The dilapidated from portion. The seemingly well dressed individual with a perfectly and unchipped glass. Just doesn''t seem to add up.</td>', 'Anti-celebration? This is a odd picture. The dilapidated from portion. The seemingly well dressed individual with a perfectly and unchipped glass. Just doesn''t seem to add up.', '2005-10-10 08:15:02.000000', NULL, 1),
(1773656, 242104, 29474, '<td valign="top">Great photograph.</td>', 'Great photograph.', '2005-10-10 08:25:38.000000', NULL, 1),
(1773658, 242237, 8624, '<td valign="top">Could have been a great action shot without the people in front of you obstructing the action. While I understand that they are celebrating, the blurry, dark shapes just harm the image.</td>', 'Could have been a great action shot without the people in front of you obstructing the action. While I understand that they are celebrating, the blurry, dark shapes just harm the image.', '2005-10-10 08:28:22.000000', NULL, 1),
(1773685, 242174, 41066, '<td valign="top">I think the shot has a lot of noise. (If you look at the skin on the peoples faces you can see it)  As for the shot itself, I love it.  They all look like their having a fantastic time and you cannot help but smile when you see the look on their faces.</td>', 'I think the shot has a lot of noise. (If you look at the skin on the peoples faces you can see it)  As for the shot itself, I love it.  They all look like their having a fantastic time and you cannot help but smile when you see the look on their faces.', '2005-10-10 09:05:40.000000', NULL, 1),
(1773692, 241948, 36199, '<td valign="top">Reminds me of the joy of youthfulness</td>', 'Reminds me of the joy of youthfulness', '2005-10-10 09:11:00.000000', NULL, 1),
(1773702, 242222, 21816, '<td valign="top">It looks a little soft to me.</td>', 'It looks a little soft to me.', '2005-10-10 09:21:20.000000', NULL, 1),
(1773705, 242098, 21816, '<td valign="top">Wow! The idea here is fantastic!</td>', 'Wow! The idea here is fantastic!', '2005-10-10 09:22:55.000000', NULL, 1),
(1773710, 242148, 29474, '<td valign="top">This is such a great picture. If the challenge was Transport or Mist or even Landscapes it would get a nine or ten. I just can''t see celebration in it.</td>', 'This is such a great picture. If the challenge was Transport or Mist or even Landscapes it would get a nine or ten. I just can''t see celebration in it.', '2005-10-10 09:26:08.000000', NULL, 1),
(1773728, 242198, 41675, '<td valign="top">Now this one makes me laugh! I love the lighting and the fabric (sheets?) the box is surrounded by. LOL - being female - it''s definitely something to celebrate! Go baby go!</td>', 'Now this one makes me laugh! I love the lighting and the fabric (sheets?) the box is surrounded by. LOL - being female - it''s definitely something to celebrate! Go baby go!', '2005-10-10 09:42:27.000000', NULL, 1),
(1773740, 242144, 37961, '<td valign="top">What a lovely moment in time for these 2 lovers. Priceless photo. 10.</td>', 'What a lovely moment in time for these 2 lovers. Priceless photo. 10.', '2005-10-10 09:53:27.000000', NULL, 1),
(1773781, 242194, 24013, '<td valign="top">aw that''s a gorgous moment.  i just love the details and that look on his face!</td>', 'aw that''s a gorgous moment.  i just love the details and that look on his face!', '2005-10-10 10:12:52.000000', NULL, 1),
(1773786, 242224, 24013, '<td valign="top">very interesting and creative shot.  i love how you''ve presented it.</td>', 'very interesting and creative shot.  i love how you''ve presented it.', '2005-10-10 10:14:37.000000', NULL, 1),
(1773792, 241890, 24013, '<td valign="top">beautiful composition and idea!</td>', 'beautiful composition and idea!', '2005-10-10 10:16:25.000000', NULL, 1),
