(1774331, 241851, 22656, '<td valign="top">Great composition, subject and toning.</td>', 'Great composition, subject and toning.', '2005-10-10 15:06:31.000000', NULL, 1),
(1774369, 241749, 45586, '<td valign="top">Very nice BW image. The tonal values are good. It is unfortunate that there are many other boats in the background. This would be good by itself and the bridge.</td>', 'Very nice BW image. The tonal values are good. It is unfortunate that there are many other boats in the background. This would be good by itself and the bridge.', '2005-10-10 15:38:30.000000', NULL, 1),
(1774382, 242089, 41675, '<td valign="top">While I''ve always liked seeing wires filled with birds, for me, I just don''t get a sense of celebration from this photo. Also, I might have cropped out the pole on the left edge completely. I wonder how this looks in color? I think seeing this particular subject matter in black and white gives it a more...darker or gloomy kind of feeling rather than celebration. IMO.</td>', 'While I''ve always liked seeing wires filled with birds, for me, I just don''t get a sense of celebration from this photo. Also, I might have cropped out the pole on the left edge completely. I wonder how this looks in color? I think seeing this particular subject matter in black and white gives it a more...darker or gloomy kind of feeling rather than celebration. IMO.', '2005-10-10 15:44:42.000000', NULL, 1),
(1774383, 242222, 41675, '<td valign="top">I like the decorations themselves, but I find the lines of the decorations combined with the lines of the ceiling kind of conflict for me visually. Also, the ceiling lights are distracting (although I know you couldn''t help those being there).</td>', 'I like the decorations themselves, but I find the lines of the decorations combined with the lines of the ceiling kind of conflict for me visually. Also, the ceiling lights are distracting (although I know you couldn''t help those being there).', '2005-10-10 15:46:03.000000', NULL, 1),
(1774385, 242067, 41675, '<td valign="top">Due to the overcast sky conditions, this photo is a bit on the dark side - at least on my monitor. However, I do like the angle on the apples. Makes me homesick for the northeast - fall, apples, cider and donuts. Thanks for the smile.</td>', 'Due to the overcast sky conditions, this photo is a bit on the dark side - at least on my monitor. However, I do like the angle on the apples. Makes me homesick for the northeast - fall, apples, cider and donuts. Thanks for the smile.', '2005-10-10 15:47:28.000000', NULL, 1),
(1774387, 241219, 41675, '<td valign="top">For me, this is kind of the opposite of celebration - or the result of too much? Bit dark and gloomy for me, but the composition is good.</td>', 'For me, this is kind of the opposite of celebration - or the result of too much? Bit dark and gloomy for me, but the composition is good.', '2005-10-10 15:48:34.000000', NULL, 1),
(1774388, 241984, 811, '<td valign="top">A marathon in 4 minutes.  Way kewl.  ;)<br/> <br/></td>', 'A marathon in 4 minutes.  Way kewl.  ;) ', '2005-10-10 15:49:44.000000', NULL, 1),
