(1776083, 240730, 35545, '<td valign="top">Just not very visually appealing.</td>', 'Just not very visually appealing.', '2005-10-11 10:14:14.000000', NULL, 1),
(1776084, 241801, 30364, '<td valign="top">Terrific, chaotic scene.  It''s a very good street-type photograph, too.  Looks almost like a snapshot at first, but it has so much more to offer.  In particular, the marvellous individual contribution to the air of exuberance &amp; celebration made by each of the six visible faces ... all different versions of the same emotions.  Love it.  8</td>', 'Terrific, chaotic scene.  It''s a very good street-type photograph, too.  Looks almost like a snapshot at first, but it has so much more to offer.  In particular, the marvellous individual contribution to the air of exuberance & celebration made by each of the six visible faces ... all different versions of the same emotions.  Love it.  8', '2005-10-11 10:14:17.000000', NULL, 1),
(1776086, 242237, 35545, '<td valign="top">I think I get what you''re driving at.  I''d have leveled the line in the backgroud above the dugout, and the out-of-focus hands/arms in front of the lense kill the shot for me.</td>', 'I think I get what you''re driving at.  I''d have leveled the line in the backgroud above the dugout, and the out-of-focus hands/arms in front of the lense kill the shot for me.', '2005-10-11 10:16:03.000000', NULL, 1),
