(1780963, 242148, 35545, '<td valign="top">I love this.</td>', 'I love this.', '2005-10-12 22:08:31.000000', NULL, 1),
(1780966, 241830, 35545, '<td valign="top">I really liked this picture until I got to the theatre entrance.  It looks as if you went overboard with the dodge tool.  I''d like to be able to see the doors, etc.  The black blob kills the p icture.</td>', 'I really liked this picture until I got to the theatre entrance.  It looks as if you went overboard with the dodge tool.  I''d like to be able to see the doors, etc.  The black blob kills the p icture.', '2005-10-12 22:11:29.000000', NULL, 1),
