(1783722, 240886, 42995, '<td valign="top">the happiness in the child''s face is obvious; great capture.  compositionally, it''s a tiny bit busy for my preference, but still nicely done.</td>', 'the happiness in the child''s face is obvious; great capture.  compositionally, it''s a tiny bit busy for my preference, but still nicely done.', '2005-10-14 10:43:52.000000', NULL, 1),
(1783726, 241725, 42995, '<td valign="top">great shot all around, the lighting, background, textures are all very nice.  well done!</td>', 'great shot all around, the lighting, background, textures are all very nice.  well done!', '2005-10-14 10:44:30.000000', NULL, 1),
(1783736, 241922, 42995, '<td valign="top">first of all, i love the expression on the baby''s face!  i love lighting and the mother''s hair, and how his little hand is grabbing her shoulder.  my one improvement would be to emphasize the ''celebration'' aspect of it, by somehow accentuating the mother''s joy.  maybe this could have been done by having the mother''s head really lean into the infant''s, or by using some kind of profile.  still, very nicely done!</td>', 'first of all, i love the expression on the baby''s face!  i love lighting and the mother''s hair, and how his little hand is grabbing her shoulder.  my one improvement would be to emphasize the ''celebration'' aspect of it, by somehow accentuating the mother''s joy.  maybe this could have been done by having the mother''s head really lean into the infant''s, or by using some kind of profile.  still, very nicely done!', '2005-10-14 10:47:28.000000', NULL, 1),
(1783748, 242144, 25742, '<td valign="top">I like this portrait of a happy couple. good luck to them and you. /8</td>', 'I like this portrait of a happy couple. good luck to them and you. /8', '2005-10-14 10:53:55.000000', NULL, 1),
(1783750, 241842, 25742, '<td valign="top">nice leaves, but the white BG isn''t doing anything for this photo.</td>', 'nice leaves, but the white BG isn''t doing anything for this photo.', '2005-10-14 10:54:26.000000', NULL, 1),
(1783754, 241851, 42995, '<td valign="top">an obviously happy child!  i like the colour and composition of this.  very nice.</td>', 'an obviously happy child!  i like the colour and composition of this.  very nice.', '2005-10-14 10:54:45.000000', NULL, 1),
(1783758, 242141, 25742, '<td valign="top">looks like something out a sci-fi flick.</td>', 'looks like something out a sci-fi flick.', '2005-10-14 10:55:19.000000', NULL, 1),
(1783764, 240914, 25742, '<td valign="top">cool. I like the energy you''ve captured there. good luck.</td>', 'cool. I like the energy you''ve captured there. good luck.', '2005-10-14 10:56:14.000000', NULL, 1),
(1783767, 242098, 42995, '<td valign="top">very nice effect; i like the colour of the train and the tilesl  well done.</td>', 'very nice effect; i like the colour of the train and the tilesl  well done.', '2005-10-14 10:56:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1783768, 242200, 25742, '<td valign="top">a sharper focus on the face would make this into a winner.</td>', 'a sharper focus on the face would make this into a winner.', '2005-10-14 10:56:46.000000', NULL, 1),
(1783771, 242084, 25742, '<td valign="top">the halos on the branches are really annoying</td>', 'the halos on the branches are really annoying', '2005-10-14 10:57:19.000000', NULL, 1),
(1783774, 242232, 25742, '<td valign="top">the "up the nostrils" look is never very flattening.</td>', 'the "up the nostrils" look is never very flattening.', '2005-10-14 10:58:30.000000', NULL, 1),
(1783776, 241720, 25742, '<td valign="top">thank you. You just made me smile on a rainy day. good luck.</td>', 'thank you. You just made me smile on a rainy day. good luck.', '2005-10-14 10:59:14.000000', NULL, 1),
(1783782, 241892, 25742, '<td valign="top">Is that you, Robert? if not, then somebody who has been studying your style. the mist is really good and gives the photo a very nice feel</td>', 'Is that you, Robert? if not, then somebody who has been studying your style. the mist is really good and gives the photo a very nice feel', '2005-10-14 11:00:23.000000', NULL, 1),
(1783789, 241801, 35739, '<td valign="top">I like the capture you have here.  Everyone is happy, so it makes the image really nice.  I like candid shots.</td>', 'I like the capture you have here.  Everyone is happy, so it makes the image really nice.  I like candid shots.', '2005-10-14 11:02:13.000000', NULL, 1),
(1783791, 241892, 35739, '<td valign="top">Above average image.</td>', 'Above average image.', '2005-10-14 11:03:39.000000', NULL, 1),
(1783795, 240755, 35739, '<td valign="top">Nice capture.</td>', 'Nice capture.', '2005-10-14 11:05:30.000000', NULL, 1),
(1783799, 241667, 42995, '<td valign="top">this is a nice photo. i like the colour of the leaf and its contrast to the grate/rake/whatever it is.  i wish that the selective blur applied around the leaf was a bit more consistent.  still, a nice job.</td>', 'this is a nice photo. i like the colour of the leaf and its contrast to the grate/rake/whatever it is.  i wish that the selective blur applied around the leaf was a bit more consistent.  still, a nice job.', '2005-10-14 11:07:15.000000', NULL, 1),
(1783805, 240730, 35739, '<td valign="top">The only thing I see is the need for longer nails and being dirty.  Good capture.</td>', 'The only thing I see is the need for longer nails and being dirty.  Good capture.', '2005-10-14 11:08:33.000000', NULL, 1),
(1783810, 241975, 42995, '<td valign="top">i think this is a great choice for the topic and i do love the girl''s obvious concentration, but i think that the ''celebration'' aspect of the photo might have come through more clearly if she was smiling.  as well, given the topic, a brighter overall shot might have made sense.  still, a nice job!</td>', 'i think this is a great choice for the topic and i do love the girl''s obvious concentration, but i think that the ''celebration'' aspect of the photo might have come through more clearly if she was smiling.  as well, given the topic, a brighter overall shot might have made sense.  still, a nice job!', '2005-10-14 11:09:18.000000', NULL, 1),
(1783815, 241014, 35739, '<td valign="top">I wish the image was a little larger.  Nice capture.</td>', 'I wish the image was a little larger.  Nice capture.', '2005-10-14 11:10:52.000000', NULL, 1),
(1783818, 242068, 42995, '<td valign="top">i like the baby''s face and the girl''s hair; wish the focus was a bit sharper.  a nice job.</td>', 'i like the baby''s face and the girl''s hair; wish the focus was a bit sharper.  a nice job.', '2005-10-14 11:12:24.000000', NULL, 1),
(1783835, 241934, 35739, '<td valign="top">A little washed out. What is that on the head of the Mallard?  Is that something in the water?</td>', 'A little washed out. What is that on the head of the Mallard?  Is that something in the water?', '2005-10-14 11:21:45.000000', NULL, 1),
(1783840, 242235, 35739, '<td valign="top">I like the capture for a personal photo in a collection, however as a challenge entry the image does not jump out to me.  You have the glare in the lens which is distracting too me.</td>', 'I like the capture for a personal photo in a collection, however as a challenge entry the image does not jump out to me.  You have the glare in the lens which is distracting too me.', '2005-10-14 11:24:04.000000', NULL, 1),
(1783850, 242089, 35739, '<td valign="top">This image does not bring out the wow in me and is a average image that does not really belong as a challenge entry.  Perhaps it is because it is dark.  A closer image of perhaps only 2-3 birds where you can see some detail. I have taken photo''s like this before, yet they were to just remember a moment in time.  I have learned that they do not score well in a challenge.  Nice try.</td>', 'This image does not bring out the wow in me and is a average image that does not really belong as a challenge entry.  Perhaps it is because it is dark.  A closer image of perhaps only 2-3 birds where you can see some detail. I have taken photo''s like this before, yet they were to just remember a moment in time.  I have learned that they do not score well in a challenge.  Nice try.', '2005-10-14 11:28:19.000000', NULL, 1),
(1783856, 242079, 35739, '<td valign="top">I wish the young man whos face is showing (the one with the black glove) should be the one in focus.  He is the center of the image.</td>', 'I wish the young man whos face is showing (the one with the black glove) should be the one in focus.  He is the center of the image.', '2005-10-14 11:30:53.000000', NULL, 1),
(1783924, 241780, 42638, '<td valign="top">Interesting picture, Lots of stuff going on in here. With such a wide shot, it is hard to see how the people are enjoying it.</td>', 'Interesting picture, Lots of stuff going on in here. With such a wide shot, it is hard to see how the people are enjoying it.', '2005-10-14 12:16:46.000000', NULL, 1),
(1783993, 241943, 36199, '<td valign="top">A beautiful image, looks so natural</td>', 'A beautiful image, looks so natural', '2005-10-14 13:03:50.000000', NULL, 1),
(1783995, 242231, 36199, '<td valign="top">Makes you smile , gives out a feeling of pure joy.</td>', 'Makes you smile , gives out a feeling of pure joy.', '2005-10-14 13:04:36.000000', NULL, 1),
(1783999, 242093, 36199, '<td valign="top">Great shot, made me laugh!</td>', 'Great shot, made me laugh!', '2005-10-14 13:05:37.000000', NULL, 1),
(1784040, 242114, 42792, '<td valign="top">A very pretty shot!  And nice image quality too.</td>', 'A very pretty shot!  And nice image quality too.', '2005-10-14 13:42:19.000000', NULL, 1),
(1784043, 242044, 42792, '<td valign="top">Such a colourful design!</td>', 'Such a colourful design!', '2005-10-14 13:44:12.000000', NULL, 1),
(1784045, 242148, 42792, '<td valign="top">Hmmm, pretty unique!  Gives a nice mood of waking up to a beautiful day where everything will go right - certainly something to celebrate.</td>', 'Hmmm, pretty unique!  Gives a nice mood of waking up to a beautiful day where everything will go right - certainly something to celebrate.', '2005-10-14 13:45:48.000000', NULL, 1),
(1784051, 241948, 42792, '<td valign="top">I think the "freedom" got lost a little as you can''t really see the movement of the horse in the frontal shot.</td>', 'I think the "freedom" got lost a little as you can''t really see the movement of the horse in the frontal shot.', '2005-10-14 13:49:58.000000', NULL, 1),
(1784052, 241747, 42792, '<td valign="top">Nice angle and colours!  Pretty original.</td>', 'Nice angle and colours!  Pretty original.', '2005-10-14 13:51:06.000000', NULL, 1),
(1784053, 242237, 42792, '<td valign="top">A bit of a pity the foreground is so dominant.  Otherwise it would have been a really nice in-action shot.</td>', 'A bit of a pity the foreground is so dominant.  Otherwise it would have been a really nice in-action shot.', '2005-10-14 13:52:30.000000', NULL, 1),
(1784058, 242096, 42792, '<td valign="top">Looks a  bit static.  Capturing the movement on a slight blur may have been more interesting.</td>', 'Looks a  bit static.  Capturing the movement on a slight blur may have been more interesting.', '2005-10-14 13:55:16.000000', NULL, 1),
(1784064, 240755, 42792, '<td valign="top">Powerful indeed!  A closer shot might have made the viewer feel the "power" more.</td>', 'Powerful indeed!  A closer shot might have made the viewer feel the "power" more.', '2005-10-14 13:57:10.000000', NULL, 1),
(1784069, 241921, 42792, '<td valign="top">Great idea!  I would have voted it higher if not for the rather distracting blue design of the tainted glass.  Just a matter of composition adjustment I think.</td>', 'Great idea!  I would have voted it higher if not for the rather distracting blue design of the tainted glass.  Just a matter of composition adjustment I think.', '2005-10-14 14:00:05.000000', NULL, 1),
(1784071, 241670, 42792, '<td valign="top">Nice scary effect indeed.  Very well done.</td>', 'Nice scary effect indeed.  Very well done.', '2005-10-14 14:00:51.000000', NULL, 1),
(1784072, 241801, 10732, '<td valign="top">this pictures has great feeling. really nice job.</td>', 'this pictures has great feeling. really nice job.', '2005-10-14 14:01:26.000000', NULL, 1),
(1784076, 241890, 10732, '<td valign="top">What a wonderful photograph.  I am sure it was fun to shoot.</td>', 'What a wonderful photograph.  I am sure it was fun to shoot.', '2005-10-14 14:03:26.000000', NULL, 1),
(1784080, 242075, 42792, '<td valign="top">Great shot!  Would have preferred a real wink (or is that a wink)?  Just looks like a squint rather than a wink : )<br/> <br/></td>', 'Great shot!  Would have preferred a real wink (or is that a wink)?  Just looks like a squint rather than a wink : ) ', '2005-10-14 14:05:13.000000', NULL, 1),
(1784081, 242231, 42792, '<td valign="top">Nice happy shot!</td>', 'Nice happy shot!', '2005-10-14 14:05:37.000000', NULL, 1),
(1784095, 241341, 42792, '<td valign="top">Like the idea but don''t find the background keeping in the spirit of the subject.</td>', 'Like the idea but don''t find the background keeping in the spirit of the subject.', '2005-10-14 14:12:41.000000', NULL, 1),
(1784101, 241413, 42792, '<td valign="top">Original and certainly a celebration in itself!</td>', 'Original and certainly a celebration in itself!', '2005-10-14 14:16:42.000000', NULL, 1),
(1784104, 242068, 42792, '<td valign="top">What a great smile!  Would have liked it better if the baby was looking into the camera as interacting with me as the viewer.</td>', 'What a great smile!  Would have liked it better if the baby was looking into the camera as interacting with me as the viewer.', '2005-10-14 14:18:09.000000', NULL, 1),
(1784109, 240914, 42792, '<td valign="top">Nice picture.  Just looks fun instead of conveying the spirit of celebration.</td>', 'Nice picture.  Just looks fun instead of conveying the spirit of celebration.', '2005-10-14 14:20:16.000000', NULL, 1),
(1784122, 241725, 45784, '<td valign="top">Love the hug. It is honest, in a way only kids can do.<br/>I also love the background. Must be an ugly wall in reality but I love it<br/>in this photo.</td>', 'Love the hug. It is honest, in a way only kids can do.I also love the background. Must be an ugly wall in reality but I love itin this photo.', '2005-10-14 14:24:46.000000', NULL, 1),
(1784127, 241556, 42792, '<td valign="top">Nice enough but the exuberance doesn''t look very convincing!</td>', 'Nice enough but the exuberance doesn''t look very convincing!', '2005-10-14 14:25:37.000000', NULL, 1),
(1784131, 241900, 42792, '<td valign="top">Pretty photo but a little too contrived in my mind.</td>', 'Pretty photo but a little too contrived in my mind.', '2005-10-14 14:26:56.000000', NULL, 1),
(1784133, 241939, 27482, '<td valign="top">Let me start off by saying that I dislike the post processing blur, it just never looks the same as having a shot in short DOF.  However, I bet I would have liked this image less if you hadn´t added the blur so if you HAD to do it afterwards, this would be the exact image to blur.  I like everything else about the shot and great job on the b/w conversion, looks very film like wich is a huge compliment as digital b/w usually looks so dull.  9 from me.</td>', 'Let me start off by saying that I dislike the post processing blur, it just never looks the same as having a shot in short DOF.  However, I bet I would have liked this image less if you hadn´t added the blur so if you HAD to do it afterwards, this would be the exact image to blur.  I like everything else about the shot and great job on the b/w conversion, looks very film like wich is a huge compliment as digital b/w usually looks so dull.  9 from me.', '2005-10-14 14:28:18.000000', NULL, 1),
(1784136, 242224, 45784, '<td valign="top">creative. A bit funny also. There is something that bugs me about this<br/>reflection in the clock (right side). But I''m a big fan of good ideas. Nice shot!</td>', 'creative. A bit funny also. There is something that bugs me about thisreflection in the clock (right side). But I''m a big fan of good ideas. Nice shot!', '2005-10-14 14:28:38.000000', NULL, 1),
(1784139, 241800, 35739, '<td valign="top">Nice!   Wish the slight glare on the childs face was not there, however I like the image.</td>', 'Nice!   Wish the slight glare on the childs face was not there, however I like the image.', '2005-10-14 14:29:57.000000', NULL, 1),
(1784141, 241851, 42792, '<td valign="top">So simply right on the feeling!  Love it and bumping it up to a 9!</td>', 'So simply right on the feeling!  Love it and bumping it up to a 9!', '2005-10-14 14:30:39.000000', NULL, 1),
(1784145, 241782, 42792, '<td valign="top">Yipee!  Great take!</td>', 'Yipee!  Great take!', '2005-10-14 14:32:01.000000', NULL, 1),
(1784149, 241852, 42792, '<td valign="top">So cool!  What a great feeling conveyed.  A definite celebration of youth, life and all things wonderful!</td>', 'So cool!  What a great feeling conveyed.  A definite celebration of youth, life and all things wonderful!', '2005-10-14 14:33:08.000000', NULL, 1),
(1784152, 241725, 42792, '<td valign="top">Such a lovely capture.  The models are great!  Bumping this up.</td>', 'Such a lovely capture.  The models are great!  Bumping this up.', '2005-10-14 14:36:19.000000', NULL, 1),
(1784171, 241842, 35739, '<td valign="top">Looks a little washed out. I do like the image and contents.  Nice colors.</td>', 'Looks a little washed out. I do like the image and contents.  Nice colors.', '2005-10-14 14:52:13.000000', NULL, 1),
(1784180, 242194, 35739, '<td valign="top">Nice capture.  The glare on the gentlemans shirt and the flower is alittle on the bright side.  Not sure but I think burning those areas, may take care of that. I am still learning PS and not sure what you could do.<br/>I do like this image. gave it a 6</td>', 'Nice capture.  The glare on the gentlemans shirt and the flower is alittle on the bright side.  Not sure but I think burning those areas, may take care of that. I am still learning PS and not sure what you could do.I do like this image. gave it a 6', '2005-10-14 14:58:10.000000', NULL, 1),
(1784230, 241943, 44334, '<td valign="top">This picture is precious. That is what life''s about.</td>', 'This picture is precious. That is what life''s about.', '2005-10-14 15:24:55.000000', NULL, 1),
(1784231, 241024, 45589, '<td valign="top">I''ve gotta get me some models to work with! Nice job.</td>', 'I''ve gotta get me some models to work with! Nice job.', '2005-10-14 15:25:30.000000', NULL, 1),
(1784232, 240730, 45589, '<td valign="top">Disturbing. Don''t see the celebration but I do enjoy a good piece of meat!</td>', 'Disturbing. Don''t see the celebration but I do enjoy a good piece of meat!', '2005-10-14 15:27:17.000000', NULL, 1),
(1784235, 241731, 45589, '<td valign="top">Interesting contrast. Celebration?</td>', 'Interesting contrast. Celebration?', '2005-10-14 15:28:21.000000', NULL, 1),
(1784390, 242148, 43759, '<td valign="top">Cool Picture!!!  You captured the fog very nicely.</td>', 'Cool Picture!!!  You captured the fog very nicely.', '2005-10-14 16:44:39.000000', NULL, 1),
(1784398, 242077, 37893, '<td valign="top">This is really very endearing. The BW works really well for this image as well as the overall tonality.</td>', 'This is really very endearing. The BW works really well for this image as well as the overall tonality.', '2005-10-14 16:53:09.000000', NULL, 1),
(1784399, 241943, 37893, '<td valign="top">Why make it private? Shout it out to the entire world :) Congratulations. Babies are God''s angels sent down to earth to make us all feel good and happy :D</td>', 'Why make it private? Shout it out to the entire world :) Congratulations. Babies are God''s angels sent down to earth to make us all feel good and happy :D', '2005-10-14 16:53:55.000000', NULL, 1),
(1784400, 241871, 37893, '<td valign="top">LOL! The lighting is a bit harsh here and the orange seems too orange. Great concept though :)</td>', 'LOL! The lighting is a bit harsh here and the orange seems too orange. Great concept though :)', '2005-10-14 16:54:35.000000', NULL, 1),
(1784402, 242114, 37893, '<td valign="top">I''ve seen a similar setup like this in another challenge :) the shadows seem a bit out of place in this image. I could bump the contrast to bring out the colors of your subject :)</td>', 'I''ve seen a similar setup like this in another challenge :) the shadows seem a bit out of place in this image. I could bump the contrast to bring out the colors of your subject :)', '2005-10-14 16:55:39.000000', NULL, 1),
(1784404, 241922, 37893, '<td valign="top">Excellent. I would have probably lit her left side just a tad so that it doesn''t completely disappear against the dark background.</td>', 'Excellent. I would have probably lit her left side just a tad so that it doesn''t completely disappear against the dark background.', '2005-10-14 16:56:24.000000', NULL, 1),
(1784411, 242148, 32321, '<td valign="top">Excellent shot. Good luck</td>', 'Excellent shot. Good luck', '2005-10-14 16:59:32.000000', NULL, 1),
(1784413, 242098, 32321, '<td valign="top">Excellent shot. Hope you post how you did this! Good luck!</td>', 'Excellent shot. Hope you post how you did this! Good luck!', '2005-10-14 17:00:57.000000', NULL, 1),
(1784461, 242229, 27421, '<td valign="top">Over sharpened?? 4.75</td>', 'Over sharpened?? 4.75', '2005-10-14 17:27:07.000000', NULL, 1),
(1784606, 241337, 5354, '<td valign="top">ROTC? - doesn''t mean anything to me. The girls look happy, but I can''t say that about the boys. I like the crop, excellent choice.</td>', 'ROTC? - doesn''t mean anything to me. The girls look happy, but I can''t say that about the boys. I like the crop, excellent choice.', '2005-10-14 18:47:18.000000', NULL, 1),
(1784609, 241341, 5354, '<td valign="top">The place where my eye comes to rest on this image is the houses in the background. Thats the most restful place, and I guess not what you wanted. <br/>Botton of the image has a solid black shadow which could be cropped off. White areas have blown out and could do with some detail (I know you probably meant this to be contrasty, but it doesn''t work for me)</td>', 'The place where my eye comes to rest on this image is the houses in the background. Thats the most restful place, and I guess not what you wanted. Botton of the image has a solid black shadow which could be cropped off. White areas have blown out and could do with some detail (I know you probably meant this to be contrasty, but it doesn''t work for me)', '2005-10-14 18:50:08.000000', NULL, 1),
(1784618, 242131, 5354, '<td valign="top">Very strangely structured image. Your title makes me think that the kid jumping is whaere I should be looking, but he''s placed too near the edge of frame to be the real subject. The other two kids have faces turned away and so neither of them can provide the main subject for me. So that leaves the ball, but that tends to get lost against the complex background.<br/> <br/>Nope my eye still keeps jumping around all those places it just won''t rest.<br/> <br/>Try to keep an image simple, provide one place for the eye to rest on. In this case simply the kid jumping in close-up would have been my choice of image.<br/> <br/>Hope that means something, and you don''t see it as simply dissing your image.</td>', 'Very strangely structured image. Your title makes me think that the kid jumping is whaere I should be looking, but he''s placed too near the edge of frame to be the real subject. The other two kids have faces turned away and so neither of them can provide the main subject for me. So that leaves the ball, but that tends to get lost against the complex background. Nope my eye still keeps jumping around all those places it just won''t rest. Try to keep an image simple, provide one place for the eye to rest on. In this case simply the kid jumping in close-up would have been my choice of image. Hope that means something, and you don''t see it as simply dissing your image.', '2005-10-14 18:55:35.000000', NULL, 1),
(1784621, 241984, 5354, '<td valign="top">Strange crop - less signage, more of the people.</td>', 'Strange crop - less signage, more of the people.', '2005-10-14 18:56:15.000000', NULL, 1),
(1784625, 241931, 5354, '<td valign="top">Yep meets the challenge, but doesn''t really make me go WOW. Its a simple static result, nice enough but needs something more.</td>', 'Yep meets the challenge, but doesn''t really make me go WOW. Its a simple static result, nice enough but needs something more.', '2005-10-14 18:58:00.000000', NULL, 1),
(1784629, 240637, 5354, '<td valign="top">I guess you are pushing the envelope here, for my interpretation of celebration anyway. I can see what you are trying to say and appreciate you are trying to differentiate your interpretation from the majority.<br/> <br/>Unfortunately the image you have decided to use is fairly lacking in a main focal point, which means the viewer can safely skip over this without having to really look at it. My guess is its probably running at 5 to 5.5, and thats probably fair.</td>', 'I guess you are pushing the envelope here, for my interpretation of celebration anyway. I can see what you are trying to say and appreciate you are trying to differentiate your interpretation from the majority. Unfortunately the image you have decided to use is fairly lacking in a main focal point, which means the viewer can safely skip over this without having to really look at it. My guess is its probably running at 5 to 5.5, and thats probably fair.', '2005-10-14 19:01:45.000000', NULL, 1),
(1784632, 242231, 5354, '<td valign="top">Nice, love the close crop and the way the background is nicely blurred. Only one small crit and thats the old lady in the back, just a second later and she would have been out of the image. As it is she pulls the eye away from the main subject just a little too much.</td>', 'Nice, love the close crop and the way the background is nicely blurred. Only one small crit and thats the old lady in the back, just a second later and she would have been out of the image. As it is she pulls the eye away from the main subject just a little too much.', '2005-10-14 19:03:51.000000', NULL, 1),
(1784634, 242099, 5354, '<td valign="top">Nice and simple, excellent.</td>', 'Nice and simple, excellent.', '2005-10-14 19:04:11.000000', NULL, 1),
(1784638, 242044, 5354, '<td valign="top">Different - nice abstract, love the shadows - they really add an extra element</td>', 'Different - nice abstract, love the shadows - they really add an extra element', '2005-10-14 19:04:52.000000', NULL, 1),
(1784647, 241683, 5354, '<td valign="top">Hmmm - dogs cats and kids - a lethal trio at DPC.<br/>Pet shots have to be something really special to make it, and to be honest this one isn''t in that small select few. <br/> <br/>Take a good look at this and ignore that its your pet. Just imagine you were not emotionally attached to the dog. What do you see?<br/>Its a snap, face on, flat lighting, blown highlights probably taken with an onboard flash which tends to give this effect.<br/> <br/>Try an image using some directional light from a window without the flash, you will see such a big difference. My guess is you are running at around 4 to 5, and thats probably fair.</td>', 'Hmmm - dogs cats and kids - a lethal trio at DPC.Pet shots have to be something really special to make it, and to be honest this one isn''t in that small select few.  Take a good look at this and ignore that its your pet. Just imagine you were not emotionally attached to the dog. What do you see?Its a snap, face on, flat lighting, blown highlights probably taken with an onboard flash which tends to give this effect. Try an image using some directional light from a window without the flash, you will see such a big difference. My guess is you are running at around 4 to 5, and thats probably fair.', '2005-10-14 19:09:58.000000', NULL, 1),
(1784648, 241782, 5354, '<td valign="top">Nice, two minor crits - the girls right hand is just cropped a little close to the edge. It feels to me as though it needs just a little more space around it.<br/>Secondly if you had been able to get up just a little more then she wouldn''t have broken the skyline with her head.<br/> <br/>Its the little details which count.</td>', 'Nice, two minor crits - the girls right hand is just cropped a little close to the edge. It feels to me as though it needs just a little more space around it.Secondly if you had been able to get up just a little more then she wouldn''t have broken the skyline with her head. Its the little details which count.', '2005-10-14 19:12:22.000000', NULL, 1),
(1784660, 240323, 5354, '<td valign="top">OK - pets, kids and toys, unless they are especially good then they tend to look like snaps. This has very obious ''snap'' giveaways - the dark shadow from onboard flash, the taps half in frame and half out of frame, the sloping and very plain background.<br/> <br/>Now, for an example of how good kid photos can be go and check out some of Jacko''s images. He used directional light either from an off camera flash or from a natural light source (window). He makes sure that the background and setting do not distract from the baby. Well worth studying some of these techniques.</td>', 'OK - pets, kids and toys, unless they are especially good then they tend to look like snaps. This has very obious ''snap'' giveaways - the dark shadow from onboard flash, the taps half in frame and half out of frame, the sloping and very plain background. Now, for an example of how good kid photos can be go and check out some of Jacko''s images. He used directional light either from an off camera flash or from a natural light source (window). He makes sure that the background and setting do not distract from the baby. Well worth studying some of these techniques.', '2005-10-14 19:16:58.000000', NULL, 1),
(1784662, 241568, 5354, '<td valign="top">Excellent, love it, and a nice pose too ;-)</td>', 'Excellent, love it, and a nice pose too ;-)', '2005-10-14 19:17:49.000000', NULL, 1),
(1784669, 242089, 5354, '<td valign="top">Good record of an natural phenomenon. Difficult to give it any artistic or technical merit though. Maybe I can force myself to see a nice sweep of wire from the top left, but apart from that I really am struggling to find much worth saying about this image. Sorry that sounds hard, but to be honest this is my current vote for brown ribbon.</td>', 'Good record of an natural phenomenon. Difficult to give it any artistic or technical merit though. Maybe I can force myself to see a nice sweep of wire from the top left, but apart from that I really am struggling to find much worth saying about this image. Sorry that sounds hard, but to be honest this is my current vote for brown ribbon.', '2005-10-14 19:23:05.000000', NULL, 1),
(1784674, 242227, 5354, '<td valign="top">Nice still life. If I had to crit something it would be that there isn''t enough space around the edge. The leaf stems almost touch the edge of the frame and I would prefer them to be a little further in.</td>', 'Nice still life. If I had to crit something it would be that there isn''t enough space around the edge. The leaf stems almost touch the edge of the frame and I would prefer them to be a little further in.', '2005-10-14 19:24:44.000000', NULL, 1),
(1784682, 241998, 5354, '<td valign="top">Nice try. Would have preferred to see the faces and to have all the hair in frame.</td>', 'Nice try. Would have preferred to see the faces and to have all the hair in frame.', '2005-10-14 19:26:08.000000', NULL, 1),
(1784683, 241747, 5354, '<td valign="top">Nice colourful image. Some strange distortions in the upper part, but I can live with that.</td>', 'Nice colourful image. Some strange distortions in the upper part, but I can live with that.', '2005-10-14 19:26:53.000000', NULL, 1),
(1784689, 241830, 5354, '<td valign="top">Not sure I like the post processing. I can''t decide whether its just a little over the top.<br/></td>', 'Not sure I like the post processing. I can''t decide whether its just a little over the top.', '2005-10-14 19:28:45.000000', NULL, 1),
(1784691, 241974, 5354, '<td valign="top">I think you already know that the front wallnut is out of focus, and that this type of image needs to be pin sharp all the way through. Shame because its nicely constructed.</td>', 'I think you already know that the front wallnut is out of focus, and that this type of image needs to be pin sharp all the way through. Shame because its nicely constructed.', '2005-10-14 19:30:26.000000', NULL, 1),
(1784699, 241679, 5354, '<td valign="top">Difficult to allocate points to this. There''s nothing to really slap the viewer in the face, it relies on the novelty of being a toilet I guess. Trouble is DPC has a wealth of other tiolet images for some strange reason and therefore the novelty falls a bit flat.<br/> <br/>I''d flush this one and sit down somewhere private and think up a different theme .... I know the ideal place ;-)</td>', 'Difficult to allocate points to this. There''s nothing to really slap the viewer in the face, it relies on the novelty of being a toilet I guess. Trouble is DPC has a wealth of other tiolet images for some strange reason and therefore the novelty falls a bit flat. I''d flush this one and sit down somewhere private and think up a different theme .... I know the ideal place ;-)', '2005-10-14 19:34:31.000000', NULL, 1),
(1784702, 242068, 5354, '<td valign="top">Nicely constructed. I get the feeling that the focus falls off just a little on the kid on the left, but thats a minor point. One of the better images in this challenge</td>', 'Nicely constructed. I get the feeling that the focus falls off just a little on the kid on the left, but thats a minor point. One of the better images in this challenge', '2005-10-14 19:35:49.000000', NULL, 1),
(1784707, 242237, 5354, '<td valign="top">Not sure if you intended this or whether it was a happy accident. Would be better without that middle arm so the viewer could actually see the action. The other arms are fine.</td>', 'Not sure if you intended this or whether it was a happy accident. Would be better without that middle arm so the viewer could actually see the action. The other arms are fine.', '2005-10-14 19:37:24.000000', NULL, 1),
(1784709, 240630, 5354, '<td valign="top">Oooh now something different at last. yes I like this, it works for me. Maybe push the circle just a little further right and lose that heavy dark band. Good work</td>', 'Oooh now something different at last. yes I like this, it works for me. Maybe push the circle just a little further right and lose that heavy dark band. Good work', '2005-10-14 19:39:07.000000', NULL, 1),
(1784712, 242235, 5354, '<td valign="top">Yes, like the idea, but the vapour trails are not the place where the eye comes to rest - they are incidental. All the leading lines drag the eye off down the pier.<br/> <br/>Also check the horizon - falls off to the right.</td>', 'Yes, like the idea, but the vapour trails are not the place where the eye comes to rest - they are incidental. All the leading lines drag the eye off down the pier. Also check the horizon - falls off to the right.', '2005-10-14 19:40:46.000000', NULL, 1),
