(1787814, 241701, 42984, '<td valign="top">This is a ribbon-winning image, but I suspect not with this challenge subject</td>', 'This is a ribbon-winning image, but I suspect not with this challenge subject', '2005-10-16 16:16:11.000000', NULL, 1),
(1787816, 241890, 42984, '<td valign="top">Cool pic, great concept.  It can stay on challenge without its title too.</td>', 'Cool pic, great concept.  It can stay on challenge without its title too.', '2005-10-16 16:17:35.000000', NULL, 1),
(1787817, 241670, 42984, '<td valign="top">I believe the image has to have some element of "celebration" in it without the Title</td>', 'I believe the image has to have some element of "celebration" in it without the Title', '2005-10-16 16:18:37.000000', NULL, 1),
(1787819, 241851, 46080, '<td valign="top">This is my favorite in the Celebration category.  We should all celebrate those simple moments, they are few and far between.  Excellent image.</td>', 'This is my favorite in the Celebration category.  We should all celebrate those simple moments, they are few and far between.  Excellent image.', '2005-10-16 16:19:05.000000', NULL, 1),
(1787821, 241634, 41675, '<td valign="top">Neat photo. I like how you carried the black from the photo into the border - it gives it all a nice balance. Looks like it was an entertaining evening. Bumping up to a 7 after second look :-)</td>', 'Neat photo. I like how you carried the black from the photo into the border - it gives it all a nice balance. Looks like it was an entertaining evening. Bumping up to a 7 after second look :-)', '2005-10-16 16:22:55.000000', NULL, 1),
(1787822, 242228, 44860, '<td valign="top">Nice shot. Message could be closer to challenge idea.</td>', 'Nice shot. Message could be closer to challenge idea.', '2005-10-16 16:23:14.000000', NULL, 1),
(1787823, 241568, 41675, '<td valign="top">Ho, ho, ho...how very cute! I think this would have done well in the redcent greeting card challenge too. Nice colors and lighting. I think the only thing I would have liked to see is the middle Santa sitting up a bit more, but still very cute.</td>', 'Ho, ho, ho...how very cute! I think this would have done well in the redcent greeting card challenge too. Nice colors and lighting. I think the only thing I would have liked to see is the middle Santa sitting up a bit more, but still very cute.', '2005-10-16 16:24:30.000000', NULL, 1),
(1787824, 241921, 42984, '<td valign="top">This has great light, movement and soul.</td>', 'This has great light, movement and soul.', '2005-10-16 16:24:44.000000', NULL, 1),
(1787827, 241679, 41675, '<td valign="top">Something each and everyone of us takes for granted, no doubt. A very good thing to celebrate - points for humor.</td>', 'Something each and everyone of us takes for granted, no doubt. A very good thing to celebrate - points for humor.', '2005-10-16 16:25:33.000000', NULL, 1),
(1787829, 242137, 42984, '<td valign="top">Perfect celebratory theme</td>', 'Perfect celebratory theme', '2005-10-16 16:26:22.000000', NULL, 1),
(1787832, 241974, 41675, '<td valign="top">I like the composition and idea. For me, I wish there was some other red or orange (say a leaf or two) to add color balance for the apple, but nicely done. I like the depth of field.</td>', 'I like the composition and idea. For me, I wish there was some other red or orange (say a leaf or two) to add color balance for the apple, but nicely done. I like the depth of field.', '2005-10-16 16:26:58.000000', NULL, 1),
(1787835, 242137, 41675, '<td valign="top">You captured a great smile on the winner''s face. For me, the blurred glittery background adds to the overall effect of a beauty-type pageant. Bumping up to a 7 after second look. Good luck in the challenge.</td>', 'You captured a great smile on the winner''s face. For me, the blurred glittery background adds to the overall effect of a beauty-type pageant. Bumping up to a 7 after second look. Good luck in the challenge.', '2005-10-16 16:28:20.000000', NULL, 1),
(1787838, 242222, 42984, '<td valign="top">The roof trusses really spoil this ... bit hard to get rid of them though I guess</td>', 'The roof trusses really spoil this ... bit hard to get rid of them though I guess', '2005-10-16 16:28:51.000000', NULL, 1),
(1787839, 241990, 41675, '<td valign="top">Yup - not being stuck in that traffic would be a reason to celebrate. For me, the color is a bit on the dark side - I wish there was more contrast to the foreground landscape tones. I like the sky. Good luck in the challenge.</td>', 'Yup - not being stuck in that traffic would be a reason to celebrate. For me, the color is a bit on the dark side - I wish there was more contrast to the foreground landscape tones. I like the sky. Good luck in the challenge.', '2005-10-16 16:29:48.000000', NULL, 1),
(1787840, 240914, 42984, '<td valign="top">What a terrific image of light and movement.  Withotu the caption though it''s hard to read celebraion into it.</td>', 'What a terrific image of light and movement.  Withotu the caption though it''s hard to read celebraion into it.', '2005-10-16 16:30:13.000000', NULL, 1),
(1787843, 242236, 41675, '<td valign="top">You''ve created a fun and colorful photo. I like the matching ribbon colors with the orange slice and glass color.</td>', 'You''ve created a fun and colorful photo. I like the matching ribbon colors with the orange slice and glass color.', '2005-10-16 16:30:52.000000', NULL, 1),
(1787848, 242139, 41675, '<td valign="top">I like your idea and composition. For me, the wine glass could use a bit more definition as the left hand side of the glass seems to have "disappeared" into the black background. My favorite part is the loaf of bread and the lighting on it. Well done.</td>', 'I like your idea and composition. For me, the wine glass could use a bit more definition as the left hand side of the glass seems to have "disappeared" into the black background. My favorite part is the loaf of bread and the lighting on it. Well done.', '2005-10-16 16:32:17.000000', NULL, 1),
(1787851, 242143, 42984, '<td valign="top">I think this is a terrific shot with the combination of the tonal greys and the filtered sky. It''s a shame that without title, it''s not very celebratory</td>', 'I think this is a terrific shot with the combination of the tonal greys and the filtered sky. It''s a shame that without title, it''s not very celebratory', '2005-10-16 16:32:44.000000', NULL, 1),
(1787853, 242044, 41675, '<td valign="top">My favorite part of your photo are the lines created by your light source (blinds?) Gives it a good graphic kind of feel for me. Good luck in the challenge. 7</td>', 'My favorite part of your photo are the lines created by your light source (blinds?) Gives it a good graphic kind of feel for me. Good luck in the challenge. 7', '2005-10-16 16:33:19.000000', NULL, 1),
(1787858, 241662, 41675, '<td valign="top">I like the private moment you captured. Very sweet. For me, I wish there had been just a bit more lighting overall, but a good entry into the challenge. Congratulations.</td>', 'I like the private moment you captured. Very sweet. For me, I wish there had been just a bit more lighting overall, but a good entry into the challenge. Congratulations.', '2005-10-16 16:34:44.000000', NULL, 1),
(1787861, 241943, 41675, '<td valign="top">A timeless treasure of a photo. For me, I would have liked to have seen a bit more of the baby as it looks a bit cut off near the head, but nicely composed and I like the black and white treatment.</td>', 'A timeless treasure of a photo. For me, I would have liked to have seen a bit more of the baby as it looks a bit cut off near the head, but nicely composed and I like the black and white treatment.', '2005-10-16 16:35:59.000000', NULL, 1),
(1787864, 241634, 42984, '<td valign="top">Good capture in difficult light</td>', 'Good capture in difficult light', '2005-10-16 16:37:15.000000', NULL, 1),
(1787865, 241720, 41675, '<td valign="top">Fun photo. Seems mayber a little bit overly saturated to me, especially in the grass areas, but that yellow rain suit jumps right out at me, and it looks like he''s having fun.</td>', 'Fun photo. Seems mayber a little bit overly saturated to me, especially in the grass areas, but that yellow rain suit jumps right out at me, and it looks like he''s having fun.', '2005-10-16 16:37:22.000000', NULL, 1),
(1787867, 241916, 42984, '<td valign="top">I wish I could see this, it looks amazing</td>', 'I wish I could see this, it looks amazing', '2005-10-16 16:38:12.000000', NULL, 1),
(1787869, 240886, 41675, '<td valign="top">A fun photo. I love how you captured her leap. Great colors. I also like how her outstretched arm is almost along the same line as the large boulder. Bumping up after second view. Good luck in the challenge. Hope you do well. 8</td>', 'A fun photo. I love how you captured her leap. Great colors. I also like how her outstretched arm is almost along the same line as the large boulder. Bumping up after second view. Good luck in the challenge. Hope you do well. 8', '2005-10-16 16:39:15.000000', NULL, 1),
(1787871, 241932, 41675, '<td valign="top">Nice photo. The colors seem a bit...muted on my screen, but it looks like it was an overcast sky when you shot this. Truly a nice thing to celebrate. I wish them many more years together. :-)</td>', 'Nice photo. The colors seem a bit...muted on my screen, but it looks like it was an overcast sky when you shot this. Truly a nice thing to celebrate. I wish them many more years together. :-)', '2005-10-16 16:40:29.000000', NULL, 1),
(1787872, 241934, 41675, '<td valign="top">How funny - I like it! Good colors. The "odd" duck is my favorite part - love that thing on it''s head.</td>', 'How funny - I like it! Good colors. The "odd" duck is my favorite part - love that thing on it''s head.', '2005-10-16 16:41:16.000000', NULL, 1),
(1787873, 241442, 41675, '<td valign="top">Nice rainbow. I wish the land masses were a bit crisper (look a bit blurred on my screen), but the expansive sky gives a nice grandeur feel.</td>', 'Nice rainbow. I wish the land masses were a bit crisper (look a bit blurred on my screen), but the expansive sky gives a nice grandeur feel.', '2005-10-16 16:42:14.000000', NULL, 1),
(1787874, 242233, 41675, '<td valign="top">Hopefully this one made it safely through the season. They''re still hunting through early Dec. where I live. Blah. Nicely composed, good colors.</td>', 'Hopefully this one made it safely through the season. They''re still hunting through early Dec. where I live. Blah. Nicely composed, good colors.', '2005-10-16 16:43:05.000000', NULL, 1),
(1787875, 240914, 41675, '<td valign="top">Fun photo. Gives me a great sense of motion. Well done.</td>', 'Fun photo. Gives me a great sense of motion. Well done.', '2005-10-16 16:43:42.000000', NULL, 1),
(1787876, 242224, 41675, '<td valign="top">I had to laugh when I saw your title as that song is one of my Jimmy Buffet favorites. I like the clock face, but not all that crazy personally about the purplish tones - although they do compliment one another. 6</td>', 'I had to laugh when I saw your title as that song is one of my Jimmy Buffet favorites. I like the clock face, but not all that crazy personally about the purplish tones - although they do compliment one another. 6', '2005-10-16 16:44:35.000000', NULL, 1),
(1787877, 241749, 41675, '<td valign="top">I like the photo and the sails, but compared with other entries in the challenge your photo doesn''t immediately say celebration to me. 6</td>', 'I like the photo and the sails, but compared with other entries in the challenge your photo doesn''t immediately say celebration to me. 6', '2005-10-16 16:45:21.000000', NULL, 1),
