(1788464, 242198, 37893, '<td valign="top">Oh now this is hard to score. LOL! Very funny and indeed a reason to celebrate not that you needed it :)</td>', 'Oh now this is hard to score. LOL! Very funny and indeed a reason to celebrate not that you needed it :)', '2005-10-16 21:09:15.000000', NULL, 1),
(1788466, 242038, 37893, '<td valign="top">Congratulations. A long married life is indeed something to smile and ecelbrate ;)</td>', 'Congratulations. A long married life is indeed something to smile and ecelbrate ;)', '2005-10-16 21:09:50.000000', NULL, 1),
