(1788470, 241932, 37893, '<td valign="top">I wish this image had more punch in the color and contrast. It''s a great concept and something to indeed celebrate :)</td>', 'I wish this image had more punch in the color and contrast. It''s a great concept and something to indeed celebrate :)', '2005-10-16 21:11:10.000000', NULL, 1),
(1788473, 242084, 37893, '<td valign="top">The branches are distracting IMHO. The simple color of the orange against the dark ground plane is a great idea.</td>', 'The branches are distracting IMHO. The simple color of the orange against the dark ground plane is a great idea.', '2005-10-16 21:11:52.000000', NULL, 1),
(1788477, 241468, 37893, '<td valign="top">There''s too many things going on in this image. The bubbles and the branches to say the least. I like the idea and it seems that this is a Filipino wedding as I see the guy wearing a Barong Tagalog :)</td>', 'There''s too many things going on in this image. The bubbles and the branches to say the least. I like the idea and it seems that this is a Filipino wedding as I see the guy wearing a Barong Tagalog :)', '2005-10-16 21:14:20.000000', NULL, 1),
