(1788481, 241828, 37893, '<td valign="top">Good toning but the harsh lighting has overblown the details in the background.</td>', 'Good toning but the harsh lighting has overblown the details in the background.', '2005-10-16 21:16:00.000000', NULL, 1),
(1788484, 241890, 42198, '<td valign="top">Bumping up to a 9. I think this meets the ''feel good'' aspect of the challenge very well. Both for the viewer, and the subject! My only small criticism is the shadow around her arms and legs. But overall ths is a great well-balanced shot.</td>', 'Bumping up to a 9. I think this meets the ''feel good'' aspect of the challenge very well. Both for the viewer, and the subject! My only small criticism is the shadow around her arms and legs. But overall ths is a great well-balanced shot.', '2005-10-16 21:17:18.000000', NULL, 1),
(1788489, 242068, 42198, '<td valign="top">An excellent capture. I love the expressions in this, especially that of the ''birthday boy''. Works well in b&amp;w. Good composition. Nice lighting (catchlights are good).</td>', 'An excellent capture. I love the expressions in this, especially that of the ''birthday boy''. Works well in b&w. Good composition. Nice lighting (catchlights are good).', '2005-10-16 21:19:42.000000', NULL, 1),
(1788493, 241024, 42198, '<td valign="top">This is just beautiful.</td>', 'This is just beautiful.', '2005-10-16 21:21:13.000000', NULL, 1),
(1788496, 240886, 42198, '<td valign="top">This is a great shot. Really captured the moment. I love the colours (gives it a polaroid feel) and the wide-angle effect is excellent, I think the clouds and the sky really add to the composition here.</td>', 'This is a great shot. Really captured the moment. I love the colours (gives it a polaroid feel) and the wide-angle effect is excellent, I think the clouds and the sky really add to the composition here.', '2005-10-16 21:22:53.000000', NULL, 1),
