(1788753, 241556, 5475, '<td valign="top">Nice shot! I''ve never seen gum that color of blue before!</td>', 'Nice shot! I''ve never seen gum that color of blue before!', '2005-10-16 23:35:49.000000', NULL, 1),
(1788756, 242060, 42198, '<td valign="top">Too much like a snapshot. There are too many distractions here, what''s the main subject? - The first thing that attracts my attention is the boy and girl on the right, followed by the couple on the left, and finally the girl carrying the balloon.... Too much going on!</td>', 'Too much like a snapshot. There are too many distractions here, what''s the main subject? - The first thing that attracts my attention is the boy and girl on the right, followed by the couple on the left, and finally the girl carrying the balloon.... Too much going on!', '2005-10-16 23:36:18.000000', NULL, 1),
