(1792901, 240755, 42984, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by roadrunner:</b></div><hr/><i> This is the trouble we have with only being able to submit small photo sizes, so we need to realise this on other photos as well, i have some great photos in print size, but reduce them to 640 and you would''nt look twice at them..... something we should keep in mind anyway...</i></td></tr></table> <br/>The 640 res is something that I like because it protects our work from being stolen and printed.  At least we all have to labour under the same restricton so it all becomes relative.<br/> <br/>Brett</td>', 'Originally posted by roadrunner: This is the trouble we have with only being able to submit small photo sizes, so we need to realise this on other photos as well, i have some great photos in print size, but reduce them to 640 and you would''nt look twice at them..... something we should keep in mind anyway... The 640 res is something that I like because it protects our work from being stolen and printed.  At least we all have to labour under the same restricton so it all becomes relative. Brett', '2005-10-18 14:40:17.000000', NULL, 0),
(1793409, 240755, 35517, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by KiwiPix:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by roadrunner:</b></div><hr/><i> This is the trouble we have with only being able to submit small photo sizes, so we need to realise this on other photos as well, i have some great photos in print size, but reduce them to 640 and you would''nt look twice at them..... something we should keep in mind anyway...</i></td></tr></table> <br/>The 640 res is something that I like because it protects our work from being stolen and printed.  At least we all have to labour under the same restricton so it all becomes relative.<br/> <br/>Brett </i></td></tr></table> <br/>yes i totally agree..<br/>sorry i wasn''t complaining about the size, just trying to explain that this particular photo doesn''t look it''s best at 640...<br/>cheers</td>', 'Originally posted by KiwiPix: Originally posted by roadrunner: This is the trouble we have with only being able to submit small photo sizes, so we need to realise this on other photos as well, i have some great photos in print size, but reduce them to 640 and you would''nt look twice at them..... something we should keep in mind anyway... The 640 res is something that I like because it protects our work from being stolen and printed.  At least we all have to labour under the same restricton so it all becomes relative. Brett  yes i totally agree..sorry i wasn''t complaining about the size, just trying to explain that this particular photo doesn''t look it''s best at 640...cheers', '2005-10-18 19:01:47.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
